contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // We test behavior for arbitrary receiver and amount, and record whether call reverted.
    function run(address receiver, uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(true);

        // capture balances before
        uint beforeC = address(c).balance;
        uint beforeThis = address(this).balance;

        bool reverted;
        // call sendTo and catch revert
        c.sendTo(receiver, amount); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint afterC = address(c).balance;
        uint afterThis = address(this).balance;

        // General rule:
        // If receiver is zero address or amount == 0 then sendTo must revert; conversely,
        // if it reverted and the parameters are non-zero/non-zero-address, it may be for other reasons
        // but balances must be unchanged whenever reverted. If it did not revert, balances must reflect transfer.
        assert((receiver == address(0) ? reverted : true) &&
               (amount == 0 ? reverted : true) &&
               (reverted ? (afterC == beforeC && afterThis == beforeThis) : (afterC <= beforeC)));
    }

    receive() external payable { }
}

